<script lang="ts">
 import {untrack} from 'svelte';
 import {get,put} from '$lib/api';
 import {Button} from '$lib/components/ui/button';
 import SceneSetup from '$lib/chat/SceneSetup.svelte';
 let {scene,newVersion=$bindable(false),disabled=false,onstate,onplan,oncontinue,onask}:{scene:string;newVersion?:boolean;disabled?:boolean;onstate?:(s:{blocking:boolean;loading:boolean})=>void;onplan?:(id:string,cost:{calls:number;seconds:number;storyboards:number})=>void;oncontinue?:()=>void|Promise<void>;onask?:(text:string)=>void}=$props();
 const cost=$derived.by(()=>{const extra=newVersion?(plan?.units??[]).filter((u:any)=>u.status==='succeeded'):[];const calls=(plan?.calls??0)+extra.length;return {calls,seconds:(plan?.new_seconds??0)+extra.reduce((n:number,u:any)=>n+u.duration,0),reused:(plan?.reused??0)-extra.length,storyboards:calls>0&&!plan?.storyboard_ready?1:0}});
 let plan=$state<any>(null),settings=$state<any>(null),loading=$state(false),saving=$state(false),dirty=$state(false),error=$state(''),setupBlocked=$state(true);let seq=0;
 function report(){onstate?.({blocking:loading||saving||dirty||!plan||!!plan.blocked||setupBlocked,loading:loading||saving})}
 async function load(){const token=++seq;loading=true;error='';report();try{const result=await get(`/scenes/${encodeURIComponent(scene)}/production`);if(token!==seq)return;if(!result?.id||!Array.isArray(result.units)||!result.settings)throw Error('The render plan is incomplete. Recheck before generating.');plan=result;settings=structuredClone(result.settings);dirty=false;}catch(e){if(token===seq){error=String(e);plan=null}}finally{if(token===seq){loading=false;report()}}}
 $effect(()=>{scene;untrack(()=>{newVersion=false;void load()})});
 $effect(()=>{const id=!dirty&&plan?plan.id:'';const quote={calls:cost.calls,seconds:cost.seconds,storyboards:cost.storyboards};untrack(()=>onplan?.(id,quote))});
 function changed(){dirty=true;error='';if(settings.audio_mode!=='native')settings.music_prompt='';report()}
 async function save(){if(disabled||loading||saving||!plan)return;const token=seq;saving=true;error='';report();try{const result=await put(`/scenes/${encodeURIComponent(scene)}/production`,{updated_at:plan.updated_at,settings:JSON.parse(JSON.stringify(settings))});if(token!==seq)return;plan=result;settings=structuredClone(result.settings);dirty=false;setupBlocked=true;}catch(e){if(token===seq)error=String(e)}finally{if(token===seq){saving=false;report()}}}
</script>
<section aria-label="Video production plan" class="space-y-3 rounded-lg border border-border p-3 text-sm">
 <div class="flex items-center justify-between gap-3"><h3 class="font-medium">Video & sound</h3><Button type="button" size="sm" variant="ghost" disabled={disabled||loading||saving} onclick={load}>Recheck plan</Button></div>
 {#if loading}<p role="status" class="text-muted-foreground">Checking clip limits and reusable videos…</p>{/if}
 {#if plan&&settings}
 <fieldset disabled={disabled||loading||saving} class="space-y-3">
 <label class="block">Audio<select aria-label="Video audio mode" class="mt-1 min-h-11 w-full rounded-md border border-input bg-background p-2" value={settings.audio_mode} onchange={e=>{settings.audio_mode=e.currentTarget.value;changed()}}>
 {#if plan.audio_supported}<option value="native">Native audio · dialogue, ambience & effects</option>{/if}<option value="saved">Saved character voices · separate speech & lip sync</option><option value="silent">Silent video</option></select></label>
 <p class="text-xs text-muted-foreground">{settings.audio_mode==='native'?'Audio is generated with the video. Exact voice identity, wording and cut timing are not guaranteed.':settings.audio_mode==='saved'?'Generate a silent visual clip, then add your saved speaker audio and lip sync.':'No generated dialogue, ambience or music. You can add audio in the editor.'}</p>
 <details><summary class="min-h-11 cursor-pointer py-2">Clips & music options</summary><div class="space-y-3 pb-2">
 <label class="block">Clip strategy<select aria-label="Clip strategy" class="mt-1 min-h-11 w-full rounded-md border border-input bg-background p-2" bind:value={settings.strategy} onchange={()=>{settings.dialogue_shots={};changed()}}><option value="auto">Automatic · group consecutive shots</option><option value="shots">Separate clip for each shot</option></select></label>
 {#if settings.audio_mode==='native'}<label class="block">Music direction <span class="text-muted-foreground">(optional)</span><textarea aria-label="Native music direction" rows="2" maxlength="1500" class="mt-1 w-full rounded-md border border-input bg-background p-2" bind:value={settings.music_prompt} oninput={changed} placeholder="Gentle piano that warms as Pip finds Mama"></textarea></label><p class="text-xs text-muted-foreground">Leave empty for dialogue and ambience only. For music spanning several clips, add one continuous track in the editor.</p>{/if}
 </div></details>
 {#if plan.units.length>1&&settings.audio_mode==='native'&&plan.lines?.length}<div class="space-y-2"><p class="text-xs text-muted-foreground">Assign each line to one clip so it is not repeated in every clip. Save the strategy first if you changed the grouping.</p>{#each plan.lines as line (line.id)}<label class="block text-xs">{line.text}<select aria-label={`Clip for dialogue ${line.id}`} class="mt-1 min-h-11 w-full rounded-md border border-input bg-background p-2" value={settings.dialogue_shots?.[line.id]??''} onchange={e=>{settings.dialogue_shots={...settings.dialogue_shots,[line.id]:e.currentTarget.value};changed()}}><option value="">Choose clip…</option>{#each plan.units as unit}<option value={unit.shot_ids[0]}>Clip {unit.index+1} · {unit.start}–{unit.start+unit.length}s</option>{/each}</select></label>{/each}</div>{/if}
 {#if dirty}<div class="flex flex-wrap items-center gap-2"><Button type="button" size="sm" disabled={saving} onclick={save}>{saving?'Saving…':'Save video options'}</Button><span class="text-xs text-muted-foreground">Save before generating</span></div>{/if}
 </fieldset>
 <label class="flex items-start gap-2 text-xs"><input type="checkbox" class="mt-1" checked={newVersion} onchange={e=>{newVersion=e.currentTarget.checked;report()}} disabled={disabled||saving||loading}/>Generate another paid version of completed clips. Active clips are always reused.</label><div role="status" aria-label="Generation cost summary" class="space-y-1 border-t border-border pt-3"><p class="font-medium">{plan.units.length} clip{plan.units.length===1?'':'s'} · {plan.edited_seconds}s final edit</p><p>{cost.calls} new paid video call{cost.calls===1?'':'s'} · {cost.seconds}s to generate · {cost.reused} existing clip{cost.reused===1?'':'s'} reused</p><p class="text-xs text-muted-foreground">Video model: {plan.model} via {plan.provider}. {plan.generated_seconds>plan.edited_seconds?`${plan.generated_seconds-plan.edited_seconds}s of model minimum-duration padding will be trimmed in the editor. `:''}{cost.storyboards?'A missing or outdated storyboard may also use image-generation quota.':cost.calls?'Current storyboard reused.':'Existing videos reused without image generation.'} Provider credits apply; no currency estimate is available.</p></div>
 {#if plan.blocked}<p role="alert" class="text-xs text-destructive">{plan.blocked}</p>{/if}
 {#key scene+plan.updated_at}<SceneSetup {scene} disabled={disabled||dirty||saving} onstate={s=>{setupBlocked=s.blocking||s.loading;report()}} {oncontinue} {onask}/>{/key}
 <Button type="button" size="sm" variant="outline" href={`/compositions?scene_id=${encodeURIComponent(scene)}`}>Assemble clips & add music</Button>
 {/if}
 {#if error}<p role="alert" class="text-xs text-destructive">{error}</p>{/if}
</section>
